  TYPE t_kwh_list IS TABLE OF NUMBER;
  v_cooling_kw NUMBER;
  v_heating_kw NUMBER;
  v_pre_total NUMBER;
  v_post_total NUMBER;
  v_usage_hours NUMBER;
  v_avg_indoor NUMBER;
  v_avg_outdoor NUMBER;
  v_output NUMBER;
  v_seff NUMBER;
  v_avg_power_kw NUMBER;
  v_carnot NUMBER;
  v_phase_heat NUMBER;
  v_flow_rate NUMBER;
  v_req_flow NUMBER;
  v_emission_factor NUMBER;
