      FROM usage_records WHERE ac_id = ac.ac_id;

    SELECT NVL(SUM(CASE WHEN "mode" = 'Cooling' THEN v_cooling_kw * usage_duration_hours
                        ELSE v_heating_kw * usage_duration_hours END), 0)
      INTO v_output
      FROM usage_records WHERE ac_id = ac.ac_id;

    IF v_pre_total > 0 THEN
      v_seff := v_output / v_pre_total;
    ELSE
      v_seff := ac.energy_efficiency_ratio;
    END IF;

    IF v_pre_total > 0 AND v_usage_hours > 0 THEN
      v_avg_power_kw := v_pre_total / v_usage_hours;
    ELSE
      v_avg_power_kw := ac.power_consumption_watts / 1000.0;
    END IF;

    IF (v_avg_outdoor - v_avg_indoor) > 0 THEN
      v_carnot := (v_avg_indoor + 273.15) / (v_avg_outdoor - v_avg_indoor);
      IF v_seff > v_carnot THEN
        v_seff := v_carnot;
      END IF;
    END IF;

    SELECT MAX(phase_change_heat_kj_per_kg), AVG(refrigerant_flow_rate_kg_per_s)
      INTO v_phase_heat, v_flow_rate
      FROM refrigerant_properties
      WHERE refrigerant_type = ac.refrigerant_type;

    IF v_phase_heat IS NULL THEN
      v_phase_heat := 200;
    END IF;
    IF v_flow_rate IS NULL THEN
      v_flow_rate := v_cooling_kw / 200;
    END IF;

    IF v_phase_heat <= 0 THEN
      CONTINUE;
    END IF;

    v_req_flow := v_cooling_kw / v_phase_heat;
    IF NOT (v_flow_rate < v_req_flow * para_flow_degradation_threshold) THEN
      CONTINUE;
