    END LOOP;

    FOR i IN 1 .. v_ids.COUNT LOOP
      DELETE FROM energy_consumption WHERE energy_id = v_ids(i);
    END LOOP;

    SELECT NVL(SUM(energy_consumption_kwh), 0) INTO v_post_total
